<?php $r = $args['record']; get_template_part( 'parts/hero', null, array( 'record' => $r, 'label' => 'Television series', 'facts' => array( 'premiere_date' => 'First aired', 'number_of_seasons' => 'Seasons', 'status' => 'Series status' ) ) );
get_template_part( 'parts/story', null, array( 'record' => $r, 'facts' => array( 'network' => 'Network', 'streaming_service' => 'Streaming', 'country' => 'Country', 'language' => 'Language', 'number_of_episodes' => 'Episodes', 'finale_date' => 'Finale' ) ) ); ?>
<section class="episode-guide"><div class="section-heading"><h2>Every episode. Every chapter.</h2><span class="eyebrow">EPISODE GUIDE</span></div>
<?php $seasons = msc_seasons( $r['uuid'] ); if ( ! $seasons ) { echo '<p class="empty-state">The episode guide is coming soon.</p>'; } foreach ( $seasons as $season => $episodes ) { echo '<h3 class="season-heading">Season ' . esc_html( 'unknown' === $season ? 'not specified' : $season ) . '</h3><ol class="episode-list">'; foreach ( $episodes as $episode ) { $episode = \MSC\Presentation::record( $episode['uuid'] ); if ( ! $episode ) { continue; } echo '<li><a href="' . esc_url( \MSC\Presentation::url( $episode ) ) . '"><span class="episode-number">' . esc_html( isset( $episode['data']['episode_number'] ) && '' !== $episode['data']['episode_number'] ? str_pad( (string) $episode['data']['episode_number'], 2, '0', STR_PAD_LEFT ) : '—' ) . '</span>' . \MSC\Presentation::image( $episode, '', 'medium' ) . '<span><strong>' . esc_html( $episode['data']['title'] ) . '</strong><small>' . esc_html( wp_trim_words( wp_strip_all_tags( $episode['data']['excerpt'] ?? '' ), 18 ) ) . '</small></span><time>' . esc_html( $episode['data']['release_date'] ?? '' ) . '</time><span aria-hidden="true"><span class="arrow" aria-hidden="true"></span></span></a>' . \MSC\Attribution::render( $episode, array( 'title', 'excerpt', 'season_number', 'episode_number', 'release_date' ) ) . \MSC\Attribution::image_html( $episode ) . '</li>'; } echo '</ol>'; } ?>
</section><?php \MSC\Presentation::credits( $r ); get_template_part( 'parts/gallery', null, $args );
